-- Disposable database only; independent fixture does not alter other contracts.
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',false);
update public.pharmacy_settings set salesperson_max_discount_percent=5 where id;
insert into public.test_ids select 'custom-med',(public.save_guided_medicine(null,
 '{"name":"Custom Price Tablets","dosage_form":"Tablet","tablets_per_strip":10,"strips_per_box":10,"units":[{"unit_key":"base","selling_price":10,"max_price":12},{"unit_key":"strip","selling_price":90},{"unit_key":"box","selling_price":800}]}',
 '{"unit_key":"box","quantity":5,"batch_number":"CUSTOM","expiry_date":"2099-12-31","total_cost":1000}',gen_random_uuid())->>'id')::uuid;
insert into public.test_ids select 'custom-owner',sale_id from public.checkout_sale(jsonb_build_array(
 jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'unit_key','base','quantity',2,'expected_price',8,'catalogue_price',10,'custom_price',8),
 jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'unit_key','strip','quantity',1,'expected_price',70,'catalogue_price',90,'custom_price',70),
 jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'unit_key','box','quantity',1,'expected_price',650,'catalogue_price',800,'custom_price',650)),
 'cash',750,6,'cccccccc-0000-4000-8000-000000000001');
select public.test_assert((select subtotal=736 and discount=6 and net_total=730 from public.sales where id=(select id from public.test_ids where label='custom-owner')),'Owner custom tablet/strip/box totals and invoice discount');
select public.test_assert((select amount=730 and tendered_amount=750 and change_amount=20 and method='cash' from public.payments where sale_id=(select id from public.test_ids where label='custom-owner')),'custom-price cash payment and change');
select public.test_assert((select sum(base_quantity)=112 and sum(line_total)=736 and sum(net_line_total)=730 from public.sale_items where sale_id=(select id from public.test_ids where label='custom-owner')),'charged prices and exact discounted line totals saved');
select public.test_assert((select unit_price=8 from public.sale_items where sale_id=(select id from public.test_ids where label='custom-owner') and selling_unit='base'),'actual charged tablet price stored');
select public.test_assert((select available_quantity=388 from public.search_sellable_medicines('Custom Price Tablets')),'custom prices preserve tablet/strip/box stock conversion');
select public.test_assert((select sum(selling_price)=900 from public.medicine_units where medicine_id=(select id from public.test_ids where label='custom-med')),'custom sale never changes permanent catalogue prices');
select * from public.checkout_sale('[]','cash',0,0,'cccccccc-0000-4000-8000-000000000001');
select public.test_assert((select count(*)=1 from public.sales where idempotency_key='cccccccc-0000-4000-8000-000000000001'),'retry returns confirmed custom sale without a second invoice');
select public.test_denied($q$select * from public.checkout_sale(jsonb_build_array(jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'quantity',1,'custom_price',13)),'cash',100,0,gen_random_uuid())$q$,'Owner cannot exceed maximum permitted unit price');
select public.test_denied($q$select * from public.checkout_sale(jsonb_build_array(jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'quantity',1,'custom_price',-1)),'cash',100,0,gen_random_uuid())$q$,'negative custom price rejected by database');
select public.test_denied($q$select * from public.checkout_sale(jsonb_build_array(jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'quantity',1,'custom_price',1.001)),'cash',100,0,gen_random_uuid())$q$,'fractional paisa rejected by database');
select public.test_denied($q$select * from public.checkout_sale(jsonb_build_array(jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'quantity',1,'custom_price','NaN')),'cash',100,0,gen_random_uuid())$q$,'nonfinite database prices rejected');
select public.test_denied($q$select * from public.checkout_sale(jsonb_build_array(jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'quantity',1,'custom_price',8,'catalogue_price',9)),'cash',100,0,gen_random_uuid())$q$,'stale catalogue price rejected even with custom price');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',false);
insert into public.test_ids select 'custom-staff',sale_id from public.checkout_sale(jsonb_build_array(jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'quantity',1,'expected_price',9.5,'catalogue_price',10,'custom_price',9.5)),'card',null,0,'cccccccc-0000-4000-8000-000000000002');
select public.test_assert((select method='card' and amount=9.5 and tendered_amount is null and change_amount=0 from public.payments where sale_id=(select id from public.test_ids where label='custom-staff')),'Salesperson custom price at five percent limit accepts card payment');
select public.test_denied($q$select * from public.checkout_sale(jsonb_build_array(jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'quantity',1,'custom_price',9.49)),'cash',100,0,gen_random_uuid())$q$,'Salesperson cannot exceed discount limit through custom price');
select public.test_denied($q$select * from public.checkout_sale(jsonb_build_array(jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'quantity',1,'custom_price',9.5)),'cash',100,0.01,gen_random_uuid())$q$,'custom reduction and invoice discount share the limit');
select public.test_denied($q$select * from public.checkout_sale(jsonb_build_array(jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'quantity',1,'custom_price',1),jsonb_build_object('medicine_id',(select id from public.test_ids where label='custom-med'),'unit_key','strip','quantity',1,'custom_price',200)),'cash',300,0,gen_random_uuid())$q$,'markup on another line cannot hide excess discount');
insert into public.test_ids select 'custom-request',public.request_sale_return((select id from public.test_ids where label='custom-staff'),(select jsonb_agg(jsonb_build_object('sale_item_id',id,'quantity',1)) from public.sale_items where sale_id=(select id from public.test_ids where label='custom-staff')),'Unopened custom-priced medicine');
select public.test_denied($q$select public.review_sale_return((select id from public.test_ids where label='custom-request'),true,'[]',null,'cash')$q$,'Salesperson requests but cannot approve custom-price refund');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',false);
select public.test_assert((select available_quantity=387 from public.search_sellable_medicines('Custom Price Tablets')),'request does not restore stock before approval');
select public.review_sale_return((select id from public.test_ids where label='custom-request'),true,(select jsonb_agg(jsonb_build_object('return_item_id',id,'approved_quantity',1,'restockable',true)) from public.return_items where return_id=(select id from public.test_ids where label='custom-request')),null,'card');
select public.test_assert((select refund_amount=9.5 from public.sale_returns where id=(select id from public.test_ids where label='custom-request')),'refund uses original custom price');
select public.test_assert((select available_quantity=388 from public.search_sellable_medicines('Custom Price Tablets')),'approval restores suitable stock once');
select public.test_denied($q$select public.review_sale_return((select id from public.test_ids where label='custom-request'),true,(select jsonb_agg(jsonb_build_object('return_item_id',id,'approved_quantity',1,'restockable',true)) from public.return_items where return_id=(select id from public.test_ids where label='custom-request')),null,'card')$q$,'duplicate approval cannot create another refund or restock');
select public.test_denied($q$select public.request_sale_return((select id from public.test_ids where label='custom-staff'),(select jsonb_agg(jsonb_build_object('sale_item_id',id,'quantity',1)) from public.sale_items where sale_id=(select id from public.test_ids where label='custom-staff')),'Duplicate return')$q$,'cannot return more than original custom sale quantity');
insert into public.test_ids select 'custom-owner-return',public.request_sale_return((select id from public.test_ids where label='custom-owner'),(select jsonb_agg(jsonb_build_object('sale_item_id',id,'quantity',quantity)) from public.sale_items where sale_id=(select id from public.test_ids where label='custom-owner')),'All unopened medicines returned');
select public.review_sale_return((select id from public.test_ids where label='custom-owner-return'),true,(select jsonb_agg(jsonb_build_object('return_item_id',id,'approved_quantity',quantity,'restockable',false)) from public.return_items where return_id=(select id from public.test_ids where label='custom-owner-return')),null,'cash');
select public.test_assert((select refund_amount=730 from public.sale_returns where id=(select id from public.test_ids where label='custom-owner-return')),'custom mixed-unit refund includes original invoice discount exactly');
select public.test_assert((select available_quantity=388 from public.search_sellable_medicines('Custom Price Tablets')),'unsuitable returned stock is never restored');
reset role;
